import { Router } from 'express';
import { ListProductStockUseCase } from '../../application/ListProductStockUseCase';

export class ProductController {
  constructor(private readonly listProductStock: ListProductStockUseCase) {}

  routes(): Router {
    const router = Router();
    router.get('/stock', (_req, res) => {
      res.json(this.listProductStock.execute());
    });
    return router;
  }
}

